const payload = (items[0] && items[0].json) || {};
const body = payload.body && typeof payload.body === 'object' ? payload.body : payload;

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
