 * The profiles that were built already, per product.
 *
 * The signature of a profile is a hash over the whole criteria of the
 * lender, so building it twice for the same product is wasted work.  The
 * cache lives on the product itself, so two products never share an entry.
 */
const CACHE = new WeakMap();

/**
 * Build the qualitative profile of a product.
 *
 * @param {object} product loan product
 * @param {string[]} unresolvedRules the narrative rules that need a model
 * @returns {{signature: string, rules: string[], facts: string[], statuses: string[]}} profile
 */
function buildProfile(product, unresolvedRules) {
  const rules = unresolvedRules === undefined ? narrativeRules(product) : unresolvedRules;
  const key = rules.join('�');
  let known = CACHE.get(product);
  if (!known) {
    known = new Map();
    CACHE.set(product, known);
  }
  const hit = known.get(key);
  if (hit) {
    return hit;
  }

  const statuses = Array.isArray(product.required_employment_statuses)
    ? product.required_employment_statuses.slice().sort()
    : [];
  const facts = referencedFacts(rules);
  const signature = fnv1a64(canonicalise({ version: 'policy-rules-v2', policy: product.criteria || {}, rules: rules.slice().sort(), statuses, facts }));
  const profile = { signature, rules, facts, statuses };
  known.set(key, profile);
  return profile;
